package ec.edu.ups.restaurant.pedidos;

import ec.edu.ups.restaurant.security.AppPrincipal;
import ec.edu.ups.restaurant.security.Tenant;
import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import java.math.BigDecimal;
import java.time.OffsetDateTime;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import org.springframework.http.HttpStatus;
import org.springframework.r2dbc.core.DatabaseClient;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.transaction.reactive.TransactionalOperator;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import reactor.core.publisher.Flux;
import reactor.core.publisher.Mono;

@RestController
@RequestMapping("/api/v1/orders")
public class OrderController {
  private static final Map<String, Set<String>> TRANSITIONS = Map.of("PENDING_DECISION", Set.of("ACCEPTED", "REJECTED"), "ACCEPTED", Set.of("PREPARING", "CANCELLED"), "PREPARING", Set.of("READY"), "READY", Set.of("COMPLETED"));
  private final DatabaseClient db; private final TransactionalOperator tx;
  public OrderController(DatabaseClient db, TransactionalOperator tx) { this.db = db; this.tx = tx; }
  public record Summary(UUID id, String publicCode, String status, String fulfillmentType, String customerName, String phone, String items, BigDecimal total, OffsetDateTime createdAt) {}
  public record Option(String type, String name, BigDecimal amount) {}
  public record Unit(UUID id, String dish, String variant, int quantity, BigDecimal unitPrice, BigDecimal extrasTotal, BigDecimal lineTotal, List<Option> options) {}
  public record Detail(UUID id, String publicCode, String status, String paymentStatus, String fulfillmentType, String customerName, String phone, String deliveryAddress, String deliveryReference, String deliveryZone, OffsetDateTime pickupTime, BigDecimal subtotal, BigDecimal deliveryFee, BigDecimal total, OffsetDateTime customerConfirmedAt, OffsetDateTime createdAt, List<Unit> units) {}
  public record TransitionInput(@NotBlank String targetStatus, String reason) {}
  public record TransitionResult(UUID orderId, String status) {}
  @GetMapping public Flux<Summary> list(@AuthenticationPrincipal AppPrincipal user) { return Tenant.restaurantId().flatMapMany(restaurantId -> summaries(restaurantId, hasRole(user, "ROLE_COCINA"))); }
  @GetMapping("/{id}") public Mono<Detail> detail(@PathVariable UUID id, @AuthenticationPrincipal AppPrincipal user) { boolean kitchen = hasRole(user, "ROLE_COCINA"); return Tenant.restaurantId().flatMap(restaurantId -> db.sql("SELECT o.id,o.status,o.payment_status,o.fulfillment_mode,o.customer_name,o.customer_phone,o.delivery_address,o.delivery_reference,z.name delivery_zone,o.pickup_time,o.subtotal,o.delivery_fee,o.total,o.confirmed_by_customer_at,o.created_at FROM customer_order o LEFT JOIN delivery_zone z ON z.id=o.delivery_zone_id AND z.restaurante_id=o.restaurante_id WHERE o.id=:id AND o.restaurante_id=:r AND (:k=false OR o.status IN ('ACCEPTED','PREPARING','READY','COMPLETED'))").bind("id", id).bind("r", restaurantId).bind("k", kitchen).map((row, metadata) -> new Base(row.get("id", UUID.class), row.get("status", String.class), row.get("payment_status", String.class), row.get("fulfillment_mode", String.class), row.get("customer_name", String.class), row.get("customer_phone", String.class), row.get("delivery_address", String.class), row.get("delivery_reference", String.class), row.get("delivery_zone", String.class), row.get("pickup_time", OffsetDateTime.class), row.get("subtotal", BigDecimal.class), row.get("delivery_fee", BigDecimal.class), row.get("total", BigDecimal.class), row.get("confirmed_by_customer_at", OffsetDateTime.class), row.get("created_at", OffsetDateTime.class))).one().switchIfEmpty(Mono.error(new ResponseStatusException(HttpStatus.NOT_FOUND, "Pedido no encontrado"))).flatMap(base -> units(restaurantId, id).collectList().map(units -> new Detail(base.id, code(base.id), base.status, base.paymentStatus, base.mode, base.customer, base.phone, base.address, base.reference, base.zone, base.pickupTime, base.subtotal, base.fee, base.total, base.confirmed, base.created, units)))); }
  @PostMapping("/{id}/transitions") @PreAuthorize("hasAnyRole('ADMIN','CAJA')") public Mono<TransitionResult> transition(@PathVariable UUID id, @RequestHeader("Idempotency-Key") @NotBlank String idempotencyKey, @Valid @RequestBody TransitionInput input, @AuthenticationPrincipal AppPrincipal user) { String target = input.targetStatus().trim().toUpperCase(); if (!TRANSITIONS.values().stream().anyMatch(targets -> targets.contains(target))) return Mono.error(new ResponseStatusException(HttpStatus.BAD_REQUEST, "Estado destino no permitido")); return Tenant.restaurantId().flatMap(restaurantId -> tx.transactional(register(restaurantId, id, idempotencyKey).flatMap(ignored -> transitionOnce(restaurantId, id, target, input.reason(), user)).switchIfEmpty(currentResult(restaurantId, id)))); }
  private Flux<Summary> summaries(UUID restaurantId, boolean kitchen) { return db.sql("SELECT o.id,o.status,o.fulfillment_mode,o.customer_name,o.customer_phone,o.total,o.created_at,COALESCE(string_agg(CONCAT('1× ',u.dish_name_snapshot), ' · ' ORDER BY u.unit_number),'Sin unidades') items FROM customer_order o LEFT JOIN order_unit u ON u.order_id=o.id AND u.restaurante_id=o.restaurante_id WHERE o.restaurante_id=:r AND (:k=false OR o.status IN ('ACCEPTED','PREPARING','READY','COMPLETED')) GROUP BY o.id,o.status,o.fulfillment_mode,o.customer_name,o.customer_phone,o.total,o.created_at ORDER BY o.created_at DESC").bind("r", restaurantId).bind("k", kitchen).map((row, metadata) -> new Summary(row.get("id", UUID.class), code(row.get("id", UUID.class)), row.get("status", String.class), row.get("fulfillment_mode", String.class), row.get("customer_name", String.class), row.get("customer_phone", String.class), row.get("items", String.class), row.get("total", BigDecimal.class), row.get("created_at", OffsetDateTime.class))).all(); }
  private Mono<UUID> register(UUID restaurantId, UUID orderId, String key) { return db.sql("INSERT INTO idempotency_operation(id,restaurante_id,operation_type,idempotency_key,result_reference) VALUES(:id,:r,:type,:key,:order) ON CONFLICT(restaurante_id,operation_type,idempotency_key) DO NOTHING RETURNING id").bind("id", UUID.randomUUID()).bind("r", restaurantId).bind("type", "ORDER_TRANSITION:" + orderId).bind("key", key).bind("order", orderId).map((row, metadata) -> row.get("id", UUID.class)).one(); }
  private Mono<TransitionResult> transitionOnce(UUID restaurantId, UUID orderId, String target, String reason, AppPrincipal user) { return db.sql("SELECT status FROM customer_order WHERE id=:id AND restaurante_id=:r FOR UPDATE").bind("id", orderId).bind("r", restaurantId).map((row, metadata) -> row.get("status", String.class)).one().switchIfEmpty(Mono.error(new ResponseStatusException(HttpStatus.NOT_FOUND, "Pedido no encontrado"))).flatMap(current -> { if (!TRANSITIONS.getOrDefault(current, Set.of()).contains(target)) return Mono.error(new ResponseStatusException(HttpStatus.CONFLICT, "La transición " + current + " → " + target + " no está permitida")); UUID correlation = UUID.randomUUID(); return db.sql("UPDATE customer_order SET status=:target,restaurant_decision_by=CASE WHEN :target='ACCEPTED' THEN :user ELSE restaurant_decision_by END WHERE id=:id AND restaurante_id=:r").bind("target", target).bind("user", user.id()).bind("id", orderId).bind("r", restaurantId).fetch().rowsUpdated().then(db.sql("INSERT INTO order_status_history(id,restaurante_id,order_id,previous_status,new_status,reason,actor_user_id,correlation_id) VALUES(:id,:r,:order,:previous,:next,:reason,:user,:correlation)").bind("id", UUID.randomUUID()).bind("r", restaurantId).bind("order", orderId).bind("previous", current).bind("next", target).bind("reason", safe(reason)).bind("user", user.id()).bind("correlation", correlation).fetch().rowsUpdated()).then(db.sql("INSERT INTO audit_log(id,restaurante_id,actor_user_id,action,entity_type,entity_id,correlation_id) VALUES(:id,:r,:user,:action,'ORDER',:order,:correlation)").bind("id", UUID.randomUUID()).bind("r", restaurantId).bind("user", user.id()).bind("action", "ORDER_STATUS_" + target).bind("order", orderId).bind("correlation", correlation).fetch().rowsUpdated()).thenReturn(new TransitionResult(orderId, target)); }); }
  private Mono<TransitionResult> currentResult(UUID restaurantId, UUID orderId) { return db.sql("SELECT status FROM customer_order WHERE id=:id AND restaurante_id=:r").bind("id", orderId).bind("r", restaurantId).map((row, metadata) -> new TransitionResult(orderId, row.get("status", String.class))).one().switchIfEmpty(Mono.error(new ResponseStatusException(HttpStatus.NOT_FOUND, "Pedido no encontrado"))); }
  private Flux<Unit> units(UUID restaurantId, UUID orderId) { return db.sql("SELECT id,dish_name_snapshot,variant_name_snapshot,base_price_snapshot,subtotal FROM order_unit WHERE restaurante_id=:r AND order_id=:o ORDER BY unit_number").bind("r", restaurantId).bind("o", orderId).map((row, metadata) -> new UnitBase(row.get("id", UUID.class), row.get("dish_name_snapshot", String.class), row.get("variant_name_snapshot", String.class), row.get("base_price_snapshot", BigDecimal.class), row.get("subtotal", BigDecimal.class))).all().concatMap(unit -> options(restaurantId, unit.id).collectList().map(options -> new Unit(unit.id, unit.dish, unit.variant, 1, unit.price, options.stream().map(Option::amount).reduce(BigDecimal.ZERO, BigDecimal::add), unit.total, options))); }
  private Flux<Option> options(UUID restaurantId, UUID unitId) { return db.sql("SELECT option_type,name_snapshot,surcharge_snapshot FROM order_unit_option WHERE restaurante_id=:r AND order_unit_id=:u ORDER BY option_type,name_snapshot").bind("r", restaurantId).bind("u", unitId).map((row, metadata) -> new Option(row.get("option_type", String.class), row.get("name_snapshot", String.class), row.get("surcharge_snapshot", BigDecimal.class))).all(); }
  private static boolean hasRole(AppPrincipal user, String role) { return user.getAuthorities().stream().anyMatch(authority -> authority.getAuthority().equals(role)); }
  private static String code(UUID id) { return "PED-" + id.toString().substring(0, 8).toUpperCase(); }
  private static String safe(String value) { return value == null ? "" : value.trim(); }
  private record Base(UUID id, String status, String paymentStatus, String mode, String customer, String phone, String address, String reference, String zone, OffsetDateTime pickupTime, BigDecimal subtotal, BigDecimal fee, BigDecimal total, OffsetDateTime confirmed, OffsetDateTime created) {}
  private record UnitBase(UUID id, String dish, String variant, BigDecimal price, BigDecimal total) {}
}
